T = {
"Runes of Spellbreaking": ("", "Cette unité peut utiliser l'aptitude « Dissipation » comme si elle avait SORCIER (1)."),
"Forgefire": ("Choisissez comme cible une unité DUARDIN CITIES OF SIGMAR amie entièrement à 12\" de cette unité, puis faites un jet de récitation d'un D6.", "Si le jet de récitation était de 10+, vous pouvez choisir une autre unité éligible comme seconde cible. Jusqu'au début de votre prochain tour, ajoutez 1 à la Perforation des armes de mêlée de chaque cible."),
"Relentless Bombardment": ("Choisissez comme cible une unité ennemie ciblée par les attaques de tir de cette unité à cette phase.", "Jetez un dé. Ajoutez 1 au résultat si cette unité est sous les ordres. Sur 3+, soustrayez 2 aux jets de charge et de course de la cible jusqu'au début de votre prochain tour."),
"Tactical Acumen": ("", "Si vous obtenez 1-3 pour déterminer la distance de déplacement de cette unité, vous pouvez utiliser une valeur de 4 à la place."),
"Piercing Bloodroar": ("Choisissez comme cibles jusqu'à 3 unités ennemies en mêlée avec cette unité.", "Jetez un dé pour chaque cible. Sur 4+, la cible ne peut pas utiliser d'ordres pour le restant du tour."),
"Relentless Hunters": ("Cette unité peut utiliser cette aptitude même si elle est dans l'ombre. S'il n'y a pas de proie ennemie, choisissez comme cible un HÉROS ennemi sur le champ de bataille. S'il n'y en a pas, choisissez une unité ennemie non HÉROS à la place.", "La cible est la proie pour le restant de la bataille."),
"Right Tools for the Job": ("", "Doublez les Dégâts des armes de mêlée de cette unité pour les attaques qui ciblent la proie ennemie."),
"Freeguild Adjutants": ("Choisissez comme cible une unité SIGMARITE amie entièrement à 12\" de cette unité et sous les ordres.", "Si cette unité est en mêlée, appliquez l'effet ci-dessous. Sinon, jetez un dé : sur 3+, appliquez-le.\nAjoutez 5 au score de contrôle de la cible jusqu'au début de votre prochain tour."),
"'For Sigmar, For Glory!'": ("", "Choisissez comme cible une unité de CAVALERIE SIGMARITE non HÉROS amie visible, entièrement à 12\" de cette unité, hors de mêlée et qui n'a pas utilisé d'aptitude de COURSE à ce tour. Après la résolution de l'ordre « Contre-charge » de cette unité, si cette unité est en mêlée, la cible peut aussitôt utiliser l'aptitude « Charge » comme si c'était votre phase de charge. De plus, vous pouvez relancer ses jets de charge pour le restant de la phase."),
"Run Down the Foe": ("Si cette unité a chargé à ce tour, choisissez comme cibles cette unité et jusqu'à 2 unités de CAVALERIE SIGMARITE non HÉROS qui ont chargé à ce tour et sont entièrement à 12\" de cette unité.", "Pour chaque cible :\n• Faites un mouvement d'engagement.\n• Puis choisissez une unité ennemie en mêlée avec la cible et jetez un D3. Sur 2+, infligez-lui autant de dégâts mortels que le résultat."),
"Coordinate Attacks": ("Choisissez comme cible une unité ennemie visible à 24\" de cette unité.", "Pour le restant du tour, ajoutez 1 aux jets de touche des attaques des unités SIGMARITE amies sous les ordres qui ciblent cette unité ennemie."),
"Combat Tactician": ("Si cette unité n'est pas en mêlée, choisissez comme cible une unité d'INFANTERIE SIGMARITE amie visible, entièrement à 18\" d'elle et hors de mêlée.", "La cible peut aussitôt utiliser l'aptitude « Mouvement Normal » comme si c'était votre phase de mouvement. De plus, elle est sous les ordres pour le restant du round de bataille."),
"Lead from the Front": ("Si cette unité est en mêlée, choisissez comme cibles chaque unité SIGMARITE amie visible entièrement à 12\" d'elle.", "Ajoutez 1 aux jets de touche et de blessure des attaques de mêlée des cibles pour le restant du tour."),
"Paralysing Venom": ("Choisissez comme cible une unité ennemie en mêlée avec cette unité.", "Jetez un dé. Si le résultat est inférieur ou égal à la Santé de la cible, soustrayez 1 aux jets de blessure de ses attaques pour le restant du tour."),
"Ghurish Ferocity": ("", "Jetez un dé. Sur 2+, ajoutez 1 aux Dégâts des Griffon's Razor Claws and Twin Beaks de cette unité pour les attaques qui ciblent des MONSTRES ennemis, pour le restant du tour."),
"Storm of Shemtek": ("Choisissez comme cible une unité ennemie visible à 12\" de cette unité.", "Faites autant de jets de D3 que le numéro du round de bataille en cours. Pour chaque 2+, infligez à la cible autant de dégâts mortels que le résultat."),
"Portents of Battle": ("Choisissez comme cible une unité CITIES OF SIGMAR amie visible entièrement à 12\" de cette unité.", "Jetez un dé. Sur 3+, ajoutez 1 aux jets de touche des attaques de mêlée de la cible jusqu'au début de votre prochain tour."),
"Steel of Helm and Heart": ("Si cette unité a au moins 5 figurines, choisissez comme cible une unité ennemie en mêlée avec elle.", "Si cette unité est sous les ordres, appliquez l'effet ci-dessous. Sinon, jetez un dé (soustrayez 1 si la cible est un MONSTRE) : sur 4+, appliquez-le.\nPour le restant du tour, si cette unité est en mêlée avec la cible quand celle-ci est choisie pour utiliser une aptitude de CORPS À CORPS :\n• Cette unité doit être choisie comme cible du mouvement d'engagement de la cible.\n• Toutes les attaques des figurines de la cible à portée de mêlée de cette unité doivent cibler cette unité."),
"Storm of Steel": ("Si cette unité est en mêlée et n'a pas chargé à ce tour, choisissez comme cibles une unité ennemie en mêlée avec elle et jusqu'à 1 Freeguild Cavalier-Marshal ami à sa portée de mêlée.", "Si cette unité est sous les ordres, appliquez l'effet ci-dessous. Sinon, jetez un dé : sur 3+, appliquez-le.\nCette unité et la cible amie peuvent utiliser l'aptitude « Charge » même si ce n'est pas votre phase de charge et même si elles sont en mêlée. Les deux unités amies doivent finir ce mouvement en mêlée avec la cible ennemie."),
"Swift Shots": ("", "Si cette unité est en mêlée, elle peut aussitôt utiliser l'aptitude « Tir » comme si c'était votre phase de tir. Toutes les attaques doivent cibler la même unité ennemie, qui doit être en mêlée avec cette unité et avoir chargé à cette phase."),
"Searing Beam of Light": ("", "Chaque fois que cette unité attaque avec son Searing Beam of Light, choisissez comme cible un point du champ de bataille à portée. Si l'attaque touche, tracez une ligne droite entre ce point et le point le plus proche du socle de cette unité. Infligez D3 dégâts mortels à chaque unité visible (amie et ennemie) traversée par la ligne."),
"Aura of Protection": ("Choisissez comme cible une unité CITIES OF SIGMAR amie visible entièrement à 12\" de cette unité.", "Jetez un dé. Sur 3+, jusqu'au début de votre prochain tour, la cible a une PROTECTION (6+) tant qu'elle est entièrement à 12\" de cette unité et visible d'elle."),
"Cinderblast Bomb": ("Si cette unité n'est pas en mêlée, choisissez comme cible une unité ennemie visible à 6\" d'elle.", "Jetez un dé. Sur 3+, infligez à la cible autant de dégâts mortels que le résultat."),
"More Pressure!": ("", "Jetez 2D6. Si le résultat est inférieur au nombre de dégâts de cette unité, infligez-lui D3 dégâts mortels. Sinon, choisissez 1 des effets suivants jusqu'au début de votre prochain tour :\nPower the Wheels : cette unité peut utiliser une aptitude de COURSE et quand même utiliser des aptitudes de TIR et/ou de CHARGE plus tard dans le tour.\nPower the Guns : ajoutez 3 aux Attaques du Steam Gun de cette unité."),
"Division Commander": ("Choisissez comme cibles jusqu'à 2 unités de Steam Tank amies.", "Pour le restant du tour, ajoutez 1 aux jets de touche des attaques de tir de cette unité et de chaque cible."),
"The Great Wheel Turns": ("", "Chaque fois qu'une figurine d'une unité SIGMARITE amie visible entièrement à 12\" de cette unité est tuée par une attaque de mêlée alors qu'elle était en mêlée avec l'unité attaquante, faites autant de jets de zèle d'un D6 que la Santé de cette figurine. Pour chaque 6+, infligez 1 dégât mortel à l'unité attaquante après la résolution de l'aptitude de CORPS À CORPS."),
"Vessel of Sigmar": ("Faites un jet de récitation d'un D6. Sur un 1 non modifié, vous pouvez relancer le dé.", "Choisissez 1 des effets suivants, ou jusqu'à 2 effets différents si le jet de récitation était de 10+.\nSanctified Ground : jusqu'au début de votre prochain tour, les unités ennemies visibles qui utilisent une aptitude de CHARGE à 9\" de cette unité ont FRAPPE EN DERNIER pour le restant du tour.\nArdent Prayers : ajoutez 1 aux jets de zèle des unités SIGMARITE amies jusqu'au début de votre prochain tour.\nCast Out Evil : jetez un D3 pour chaque SORCIER et PRÊTRE ennemi visible sur le champ de bataille. Sur 2+, infligez-lui autant de dégâts mortels que le résultat."),
"Guardian and Mentor": ("", "Tant que cette unité compte 2 figurines, elle a une PROTECTION (5+)."),
"Weapons of Banishment": ("Choisissez comme cible une unité SIGMARITE amie visible entièrement à 12\" de cette unité et sous les ordres.", "Jusqu'au début de votre prochain tour, tant que la cible est entièrement à 12\" de cette unité et sous les ordres, ajoutez 1 aux Dégâts de ses armes pour les attaques de mêlée qui ciblent des SORCIERS, PRÊTRES et MANIFESTATIONS ennemis."),
"Protective Focus": ("", "Choisissez une aptitude de SORT que cette unité peut utiliser. Pour le restant de la bataille, aucun dégât mortel n'est infligé à cette unité si elle fait un fiasco en lançant ce sort."),
"Fearless Leader": ("", "Choisissez comme cible une unité DUARDIN CITIES OF SIGMAR amie à portée de mêlée de cette unité qui n'a pas utilisé d'aptitude de CORPS À CORPS à ce tour. Elle peut utiliser une aptitude de CORPS À CORPS juste après celle de cette unité."),
"Ancestral Grudgebearer": ("Choisissez une unité ennemie de l'armée adverse comme cible de rancune. Vous pouvez choisir une unité en réserve.", "Pour le restant de la bataille, ajoutez 1 aux jets de blessure des attaques de mêlée des unités DUARDIN CITIES OF SIGMAR amies qui ciblent cette unité."),
"Blackpowder Squire": ("", "Le Blackpowder Squire de cette unité est un pion. Retirez-le du champ de bataille, puis ajoutez 1 à la Perforation des armes de tir de cette unité pour le restant du tour."),
"Fortified Position": ("", "Tant que cette unité est sous les ordres :\n• Ses armes de tir ont Tir en mêlée.\n• Soustrayez 1 à la Perforation des armes utilisées pour les attaques qui la ciblent."),
"'I Thought Duardin Were Made of Sterner Stuff!'": ("Choisissez comme cible une autre unité DUARDIN CITIES OF SIGMAR amie entièrement à 12\" de cette unité. Vous ne pouvez pas choisir une unité de Longbeards.", "Jetez un dé. Sur 3+, ajoutez 1 aux jets de blessure des attaques de mêlée de la cible pour le restant du tour."),
"Oathsworn": ("", "Tant qu'un ou plusieurs Warden Kings amis sont entièrement à portée de mêlée de cette unité, cette unité et ces Warden Kings ont une PROTECTION (5+)."),
"Gromril Shieldwall": ("", "Si cette unité n'a pas utilisé d'aptitude de MOUVEMENT à ce tour et n'a pas été placée à ce tour, les attaques qui la ciblent ne peuvent pas causer de touches critiques (elles comptent comme des touches normales)."),
"Grudgebuster Bombs": ("Si cette unité a utilisé une aptitude de MOUVEMENT à cette phase, choisissez comme cible une unité ennemie sans VOL qu'elle a traversée à ce tour.", "Choisissez 1 des effets suivants :\nTactical Bombing : jetez un D3. Sur 2+, infligez à la cible autant de dégâts mortels que le résultat.\nDrop It All! : faites 2 jets de D3. Pour chaque 2+, infligez à la cible autant de dégâts mortels que le résultat. Puis jetez un D3 pour chaque unité (amie et ennemie) sans VOL à portée de mêlée de la cible. Sur 2+, infligez-lui autant de dégâts mortels que le résultat. Une fois l'effet Drop It All! résolu, cette unité ne peut plus utiliser cette aptitude pour le restant de la bataille."),
"'At Them, You Curs!'": ("", "Choisissez comme cible une unité de Black Ark Corsairs amie à portée de mêlée de cette unité qui n'a pas utilisé d'aptitude de CORPS À CORPS à ce tour. Elle peut utiliser une aptitude de CORPS À CORPS juste après celle de cette unité. Si elle le fait, ajoutez 1 aux Attaques de ses armes de mêlée pour le restant du tour."),
"Guild Bombs": ("Si cette unité a utilisé une aptitude de MOUVEMENT à cette phase, choisissez comme cible une unité ennemie sans VOL qu'elle a traversée à ce tour.", "Jetez un D3. Sur 2+, infligez à la cible autant de dégâts mortels que le résultat."),
"Direct the Gyrocorps": ("Choisissez comme cibles jusqu'à 3 unités de Gyrocopters ou de Gyrobombers amies visibles entièrement à 18\" de cette unité.", "Jetez un dé pour chaque cible. Sur 3+, jusqu'au début de votre prochain tour :\n• Ajoutez 1 aux jets de touche de ses attaques.\n• Ajoutez 2\" à son Mouvement."),
"Prize Specimens": ("", "Pour le restant du tour, ajoutez 1 aux jets de touche et de blessure des attaques de tir de cette unité qui ciblent des MONSTRES ennemis."),
"Glorious Martyrs": ("", "Tant qu'un PRÊTRE SIGMARITE ami est entièrement à portée de mêlée de cette unité, ajoutez 1 aux jets de blessure de ses attaques de mêlée."),
"Storm of Iron-tipped Bolts": ("", "Si cette unité n'a pas utilisé d'aptitude de MOUVEMENT à ce tour et n'a pas été placée à ce tour, ajoutez 1 aux Attaques de ses Master-crafted Repeater Crossbows pour le restant du tour."),
"Command Underlings": ("Choisissez comme cibles jusqu'à 3 unités d'INFANTERIE AELF CITIES OF SIGMAR amies entièrement à 12\" de cette unité.", "Ajoutez 3\" au Mouvement de chaque cible pour le restant du tour."),
"Feed on Life Force": ("Choisissez comme cible une unité ennemie en mêlée avec cette unité.", "Jetez un D3. Sur 2+, infligez à la cible autant de dégâts mortels que le résultat. Si des figurines ennemies sont tuées par cette aptitude, placez un pion de sorcellerie noire à côté de cette unité pour le restant de la bataille (3 maximum)."),
"Dark Sorcery": ("", "Ajoutez 1 aux jets de lancement de cette unité pour chaque pion de sorcellerie noire qu'elle a."),
"Coven Guard": ("", "Si cette unité n'a pas chargé à ce tour, ajoutez 1 aux jets de blessure de ses attaques pour le restant du tour."),
"Merciless Conquerors": ("", "Pour le restant du tour, ajoutez 1 aux Attaques des armes de mêlée de cette unité tant qu'elle conteste un objectif que vous ne contrôlez pas."),
"Severing Strike": ("", "Si cette unité a chargé à ce tour, ses armes de mêlée ont Crit (Mortel)."),
"Goaded and Whipped": ("", "Doublez les Attaques des armes de mêlée Compagnon de cette unité pour le restant du tour."),
"Abyssal Howl": ("Choisissez comme cible une unité ennemie en mêlée avec cette unité.", "Jetez un dé. Sur 3+, le score de contrôle de la cible est de 1 maximum pour le restant du tour."),
"Indiscriminate Slaughter": ("Choisissez comme cibles chaque autre unité (amie et ennemie) à portée de mêlée de cette unité.", "Jetez un D3 pour chaque cible. Sur 2+, infligez-lui autant de dégâts mortels que le résultat."),
"Under the Shadow of Black Wings": ("", "Ajoutez 1 aux jets de charge des unités de CAVALERIE AELF CITIES OF SIGMAR amies tant qu'elles sont entièrement à 12\" de cette unité."),
"Sow Havoc": ("Choisissez comme cible une unité ennemie en mêlée avec cette unité.", "Jetez un dé. Sur 3+ :\n• Infligez D3 dégâts mortels à la cible.\n• Cette unité peut aussitôt utiliser l'aptitude « Repli » comme si c'était votre phase de mouvement, sans subir de dégâts mortels."),
"Bestial Instincts": ("", "Pour le restant du tour, ajoutez 1 aux Attaques des Drakespawn's Ferocious Jaws de cette unité tant qu'elle est en mêlée avec des unités ennemies auxquelles des dégâts ont été alloués à cette phase ou qui ont perdu des figurines à cette phase."),
"Cruel Sacrifice": ("Choisissez comme cible une unité AELF CITIES OF SIGMAR amie visible entièrement à 6\" de cette unité.", "Ajoutez 1 aux jets de lancement de cette unité pour le restant du tour. Puis jetez un dé. Sur 4+, 1 figurine de la cible est tuée."),
"Word of Pain": ("Choisissez comme cible une unité ennemie en mêlée avec cette unité.", "Jetez un dé. Sur 3+, soustrayez 1 aux jets de touche et de blessure des attaques de la cible jusqu'au début de votre prochain tour."),
"Hidden Murderer": ("", "Tant que cette unité est à portée de mêlée d'une unité d'INFANTERIE amie d'au moins 5 figurines et qu'aucune unité ennemie n'est à sa portée de mêlée, elle n'est pas visible des unités ennemies."),
"In for the Kill": ("", "Cette unité a FRAPPE EN PREMIER si elle a chargé au même tour."),
"Steel and Sorcery": ("", "Tant qu'un ou plusieurs HÉROS d'INFANTERIE AELF CITIES OF SIGMAR amis sont entièrement à portée de mêlée de cette unité, cette unité et ces unités amies ont une PROTECTION (5+)."),
"Scythed Runners": ("Si cette unité a chargé à cette phase, choisissez comme cible une unité ennemie à 1\" d'elle.", "Jetez un D3. Sur 2+, infligez à la cible autant de dégâts mortels que le résultat."),
"Impossible To Destroy": ("", "Soignez (6) cette unité."),
"Six-headed Strike": ("Choisissez comme cible une unité ennemie en mêlée avec cette unité.", "Jetez 6 dés. Pour chaque 3+, infligez 1 dégât mortel à la cible."),
"Front-line Commander": ("", "Si cette unité est sous les ordres, choisissez comme cible une unité d'INFANTERIE ou un MONSTRE SIGMARITE ami, entièrement à 12\" de cette unité ou ayant son Relic Envoy à côté, qui n'a pas utilisé d'aptitude de CORPS À CORPS à ce tour. Elle peut utiliser une aptitude de CORPS À CORPS juste après celle de cette unité. Si elle le fait, elle peut utiliser 2 aptitudes de CORPS À CORPS à cette phase. Après la première, elle a FRAPPE EN DERNIER pour le restant du tour."),
"Attendant Relic Envoy": ("Le Relic Envoy de cette unité est un pion. Choisissez comme cible une unité SIGMARITE amie visible entièrement à 18\" de cette unité et qui n'est pas sous les ordres.", "Placez le Relic Envoy de cette unité à côté de la cible. Tant que cette unité est sous les ordres et sur le champ de bataille, et que son Relic Envoy est à côté de la cible, la cible est sous les ordres."),
"Runic Crucible": ("Choisissez comme cible une unité SIGMARITE amie visible entièrement à 12\" de cette unité.", "Faites un jet de manipulation arcanique d'un D6. Sur 3+, les armes de mêlée de la cible ont Crit (Mortel) jusqu'au début de votre prochain tour."),
"Expert Pathfinders": ("Choisissez cette unité et jusqu'à 2 unités SIGMARITE non MONSTRE et non MACHINE DE GUERRE amies, si aucune n'a été déployée.", "Placez ces unités en réserve, en éclaireurs. Elles sont à présent déployées."),
"Prepared Arrival": ("Choisissez cette unité si elle est en éclaireur.", "Placez cette unité entièrement à 9\" d'un bord du champ de bataille et à plus de 9\" des unités ennemies. Puis placez chaque autre unité amie en éclaireur entièrement à 12\" de cette unité et à plus de 9\" des unités ennemies."),
"Aggressive Defenders": ("Choisissez comme cibles jusqu'à 3 autres unités SIGMARITE amies visibles, en mêlée avec des unités ennemies qui sont en mêlée avec cette unité.", "Chaque cible peut utiliser des aptitudes de TIR et/ou de CHARGE même si elle a utilisé une aptitude de REPLI à ce tour. De plus, aucun dégât mortel ne leur est infligé par les aptitudes de REPLI pour le restant du tour."),
"Open the Gates!": ("Choisissez comme cible une unité CITIES OF SIGMAR non MACHINE DE GUERRE amie visible entièrement à 12\" de cette unité.", "Ajoutez 2 aux jets de charge de la cible pour le restant du tour."),
"Consecrate the Land": ("Choisissez comme cible un objectif que vous contrôlez et que cette unité conteste.", "S'il n'y a pas d'unité ennemie contestant l'objectif, il est consacré pour vous. Sinon, jetez un dé : sur 3+, il est consacré pour vous.\nTant qu'elles sont entièrement à 6\" d'un objectif consacré et sous les ordres :\n• Les unités SIGMARITE non MACHINE DE GUERRE amies ont une PROTECTION (5+).\n• Les MACHINES DE GUERRE SIGMARITE amies ont une PROTECTION (6+).\nSi votre adversaire prend le contrôle d'un objectif consacré, il n'est plus consacré."),
"Not One Step Back": ("", "Si cette unité n'a pas chargé à ce tour, ajoutez 1 aux Attaques et aux Dégâts de ses armes de mêlée."),
"Break Them Upon the Walls": ("", "Tant que cette unité est sous les ordres, les armes de mêlée des autres unités SIGMARITE amies visibles, hors Freeguild Gallants, ont Anti-charge (+1 Perf.) tant qu'elles sont entièrement à 12\" de cette unité."),
"Incandescent Incineration": ("Choisissez comme cible une unité ennemie visible à 12\" de cette unité, puis faites un jet de lancement de 2D6.", "Si la cible n'était pas incandescente quand elle a été choisie :\n• Infligez-lui D3 dégâts mortels.\n• Elle est incandescente pour le restant de la bataille.\nSi la cible était incandescente :\n• Allouez-lui 3 dégâts (aucun jet de protection ne peut être fait pour ces dégâts).\n• Elle n'est plus incandescente."),
"The Flames of Aqshy": ("", "Faites un jet de manipulation arcanique d'un D6. Sur 3+, pour le restant du tour, pour choisir la cible de l'aptitude « Incandescent Incineration », vous pouvez choisir une unité ennemie visible à 18\" de cette unité au lieu de 12\"."),
"Harrying Attacks": ("", "Tant que la Thexa de cette unité est à côté d'une unité ennemie, les attaques de cette unité ennemie ne peuvent pas causer de touches critiques (elles comptent comme des touches normales)."),
"Prowling Ash Panther": ("La Thexa de cette unité est un pion. Si elle n'est pas sur le champ de bataille, choisissez comme cible une unité ennemie en mêlée avec cette unité.", "Placez la Thexa de cette unité à côté de la cible, puis jetez un D3. Sur 2+, infligez à la cible autant de dégâts mortels que le résultat. Si la cible est détruite alors que la Thexa est à côté d'elle, retirez la Thexa du champ de bataille."),
"Fluid Combat Style": ("", "Juste après la résolution de l'aptitude de CORPS À CORPS de cette unité, choisissez un point du champ de bataille à 6\" d'elle et à plus de 3\" de toutes les unités (amies et ennemies) et des éléments de terrain. Retirez l'unité qui a utilisé l'aptitude du champ de bataille et replacez-la entièrement à 6\" de ce point et hors de mêlée."),
"Cinders and Ashes": ("Si cette unité contient un Cindergout, choisissez un élément de terrain ou un objectif qu'elle conteste, puis choisissez comme cibles les unités ennemies qui le contestent.", "Jetez un D3 pour chaque cible. Sur 2+, infligez-lui autant de dégâts mortels que le résultat."),
"Seize the Souls": ("Si cette unité contient un Soul Shepherd, choisissez comme cible une unité ennemie visible à 18\" d'elle.", "Jetez un dé. Sur 3+, la cible ne peut pas être soignée ni récupérer de figurines tuées jusqu'au début de votre prochain tour."),
"Field Surgery": ("Si cette unité est hors de mêlée et contient un War Surgeon, choisissez comme cible une unité SIGMARITE non MACHINE DE GUERRE amie visible entièrement à 12\" d'elle.", "Jetez un dé. Sur 3+ :\nSi la cible est une unité d'INFANTERIE non HÉROS, ramenez-y D3 figurines tuées.\nSi la cible est une unité de CAVALERIE non HÉROS, ramenez-y 1 figurine tuée.\nSi la cible est un HÉROS ou un MONSTRE, Soignez (D3) la cible."),
"Lurking Spymaster": ("", "Cette unité ne peut ni utiliser ni être choisie comme cible de l'aptitude « Form Up ».\nTant qu'elle est à portée de mêlée d'une unité d'INFANTERIE SIGMARITE amie d'au moins 3 figurines, et qu'aucun autre Whisperblade ami n'est à portée de mêlée de cette unité, elle ne peut pas être choisie comme cible d'attaques de tir ou de mêlée."),
"Deathly Candlelight": ("Choisissez comme cible une unité ennemie visible à 12\" de cette unité, puis faites un jet de lancement de 2D6.", "La cible ne peut pas utiliser d'ordres pour le restant du tour."),
"Ominous Presence": ("", "Faites un jet de manipulation arcanique d'un D6. Sur 3+, pour le restant du tour, pour choisir la cible de l'aptitude « Deathly Candlelight », vous pouvez choisir une unité ennemie visible à 18\" de cette unité au lieu de 12\"."),
"Full Charge!": ("", "Choisissez 1 ou plusieurs des effets suivants. Pour chaque effet choisi, donnez à cette unité autant de pions de chaleur que le nombre indiqué.\n1 Breaching Assist! : si cette unité utilise l'aptitude « Sally Forth » à ce tour, les armes de mêlée des cibles de cette aptitude ont Charge (+1 dégât) pour le restant du tour.\n2 Full Throttle : pour le restant du tour, le Mouvement de cette unité est de 10\".\n3 Repel Boarders! : pour le restant du tour, ajoutez 2 aux Attaques des Leadshotters et des Crushing Iron Feet de cette unité.\n4 Disengage Safeties! : pour le restant du tour, les Attaques du Realmscorcher Flame Cannon de cette unité sont de 22.\n6 Get Us Out of Here! : pour le restant du tour, cette unité peut utiliser des aptitudes de TIR même si elle a utilisé une aptitude de REPLI au même tour."),
"Overheating": ("", "Juste après la résolution de l'aptitude « Full Power! » de cette unité, vous devez jeter autant de dés qu'elle a de pions de chaleur. Pour chaque 5+, allouez-lui 1 dégât (aucun jet de protection ne peut être fait pour ces dégâts), puis retirez 1 de ses pions de chaleur."),
"All Aboard!": ("Choisissez jusqu'à 1 HÉROS d'INFANTERIE SIGMARITE ami et jusqu'à 1 unité d'INFANTERIE SIGMARITE non HÉROS amie qui n'ont pas été déployés.", "Placez ces unités en réserve, comme passagers de cette unité. Elles sont à présent déployées."),
"Sally Forth": ("Si cette unité n'a pas utilisé d'aptitude de COURSE à ce tour, choisissez ses passagers comme cibles.", "Placez chaque cible entièrement à 6\" de cette unité, soit hors de mêlée, soit à ½\" d'une unité ennemie. Une cible placée en mêlée a chargé. Puis, si cette unité n'est pas sous les ordres, cette unité et les cibles sont sous les ordres pour le restant du round de bataille."),
"Full Power!": ("", "Choisissez 1 ou plusieurs des effets suivants. Pour chaque effet choisi, donnez à cette unité autant de pions de chaleur que le nombre indiqué.\n1 Launch Countermeasures! : jusqu'au début de votre prochain tour, soustrayez 1 aux jets de touche des attaques de tir qui ciblent les autres unités SIGMARITE amies tant qu'elles sont entièrement à 12\" de cette unité et sous les ordres.\n2 Full Throttle : pour le restant du tour, le Mouvement de cette unité est de 10\".\n3 Calculate Firing Solution! : pour le restant du tour, chaque fois que cette unité utilise une aptitude de TIR, vous pouvez relancer 1 jet de touche et 1 jet de blessure des attaques de son Godbreaker Cannon.\n6 Get Us Out of Here! : pour le restant du tour, cette unité peut utiliser des aptitudes de TIR même si elle a utilisé une aptitude de REPLI au même tour."),
"Special Ammunition": ("", "Si cette unité est sous les ordres, jetez un dé. Sur 3+, choisissez 1 des effets suivants :\nNullshot : soustrayez 1 aux jets de protection contre les dégâts infligés par les attaques du Godbreaker Cannon de cette unité à cette phase.\nHeavy Shot : ajoutez 1 à la Perforation du Godbreaker Cannon de cette unité à cette phase.\nGrapeshot : après la résolution de l'aptitude de TIR, si toutes les attaques du Godbreaker Cannon ont ciblé la même unité ennemie, infligez D3 dégâts mortels à chaque autre unité ennemie à portée de mêlée de celle-ci."),
"Lantern of All-Knowledge": ("", "Si cette unité est entièrement à 9\" d'un coin du champ de bataille, choisissez 1 des effets suivants jusqu'au début de votre prochain tour :\nSearing Brilliance : les unités SIGMARITE amies ne sont pas visibles des unités ennemies à plus de 6\" d'elles tant qu'elles sont entièrement à 6\" de cette unité et visibles d'elle.\nLambent Aura : ajoutez 1 au niveau de puissance de cette unité.\nLuminous Authority : ajoutez 2 aux jets de manipulation arcanique de cette unité.\nPrismatic Diffusion : ajoutez 3 aux Attaques du Rod of Radiance de cette unité et fixez ses Dégâts à 3."),
"Realmsphere Mastery": ("Choisissez comme cible une MANIFESTATION ennemie visible à 12\" de cette unité qui n'a pas été placée à ce tour.", "Faites un jet de manipulation arcanique de 2D6. Si le résultat est supérieur ou égal à la valeur de bannissement de la cible, placez un SORT PERSISTANT que cette unité peut invoquer avec un sort d'INVOCATION, à 1\" de la cible et à plus de 3\" des unités ennemies et des autres MANIFESTATIONS ennemies. S'il a plusieurs parties, elles doivent toutes être placées à 1\" de la cible. Cette unité a invoqué ce SORT PERSISTANT. Si un SORT PERSISTANT ami du même type est déjà sur le champ de bataille, il est aussitôt banni et retiré du jeu avant le placement. Puis la cible est bannie et retirée du jeu."),
"The Four Corners of the Realms": ("Faites un jet de lancement de 2D6.", "Retirez cette unité du champ de bataille et replacez-la entièrement à 9\" d'un coin du champ de bataille et à plus de 3\" des unités ennemies."),
"Sigmar's Blessing": ("Choisissez comme cible une unité SIGMARITE amie visible entièrement à 12\" de cette unité, puis faites un jet de récitation d'un D6.", "Jusqu'au début de votre prochain tour :\n• Les armes de mêlée de la cible ont Charge (+1 dégât).\n• Si le jet de récitation était de 10+, la cible a une PROTECTION (5+) si elle a chargé au même tour."),
"Unquenchable Faith": ("", "Si cette unité devait être détruite, avant de la retirer du jeu, elle peut aussitôt utiliser l'aptitude « Sigmar's Blessing » comme si c'était votre phase des héros. Dans ce cas :\n• Cette prière ne compte pas dans le nombre d'aptitudes de PRIÈRE que cette unité peut utiliser à cette phase.\n• Au lieu de faire un jet de récitation, vous devez utiliser une valeur de 10, qui ne peut pas être modifiée.\n• L'effet de cette prière s'applique pour le restant de la bataille au lieu de jusqu'au début de votre prochain tour."),
"Crucible of Rage": ("", "Vous pouvez dépenser 1 dé de rage. Si vous le faites :\n• Appliquez l'effet ci-dessous.\n• Si le niveau de fureur de votre adversaire est inférieur au vôtre, il doit l'augmenter de 1 (7 maximum).\nSinon, jetez un dé : sur 3+, appliquez l'effet ci-dessous.\nJusqu'au début de votre prochain tour, ajoutez 1 aux jets de lancement des unités CITIES OF SIGMAR amies tant qu'elles sont entièrement à 6\" de cette unité."),
"Form Up": ("Choisissez une unité CITIES OF SIGMAR amie pour utiliser cette aptitude, puis choisissez comme cibles 2 autres unités CITIES OF SIGMAR amies visibles entièrement à 12\" d'elle. L'unité qui utilise l'aptitude et les cibles ne doivent pas être sous les ordres et doivent toutes être de types d'unité différents.", "Pour le restant du round de bataille, l'unité qui utilise cette aptitude et les cibles sont sous les ordres.\nNote : le « type d'unité » est le nom du warscroll (Règles de Base, 4.0), par exemple « Freeguild Cavalier-Marshal » ou « Cannonade Cogfort »."),
"Take Aim": ("Choisissez une unité amie sous les ordres pour utiliser cette aptitude.", "Choisissez une de ses armes de tir. Ajoutez 1 aux jets de touche des attaques de tir faites avec cette arme pour le restant du tour."),
"Sound the Attack": ("", "Vous pouvez remplacer le D6 le plus bas du jet de charge par la valeur du D6 le plus haut."),
"Into Them, You Dogs!": ("Choisissez un HÉROS ami sous les ordres pour utiliser cette aptitude : il est l'officier de terrain pour le restant du tour. Puis choisissez comme cibles 2 autres unités non HÉROS amies visibles, sous les ordres et entièrement à 12\" de l'officier de terrain.", "Pour le restant du tour, la première fois que l'officier de terrain utilise une aptitude de CORPS À CORPS, vous pouvez choisir une cible qui n'a pas utilisé d'aptitude de CORPS À CORPS à ce tour : elle est galvanisée, et l'autre cible est enhardie. La cible galvanisée peut utiliser une aptitude de CORPS À CORPS juste après celle de l'officier de terrain. Puis, si la cible enhardie n'a pas utilisé d'aptitude de CORPS À CORPS à ce tour, elle peut en utiliser une juste après celle de la cible galvanisée."),
"Hurl Them Back!": ("Choisissez pour utiliser cette aptitude une unité amie sous les ordres et en mêlée avec une unité ennemie qui a chargé à ce tour.", "Pour le restant du tour, ajoutez 1 à la Perforation des armes de mêlée de cette unité."),
"The Last Blade of Embergard": ("", "Cette unité peut utiliser cette aptitude tant qu'elle est en réserve. Choisissez une de ses armes de mêlée non Compagnon. Ajoutez 2 à ses Attaques et à sa Perforation pour le restant de la bataille."),
"Bones of Saint Ignifus": ("", "Ajoutez 1 au jet de lancement ou de récitation de cette aptitude."),
"The Sphere Celestial": ("Si cette unité est hors de mêlée, choisissez comme point cible un point du champ de bataille à 1\" de cette unité et à plus de 3\" de toutes les autres unités (amies et ennemies) et des éléments de terrain. Puis choisissez comme unité cible un autre HÉROS d'INFANTERIE ou de CAVALERIE CITIES OF SIGMAR ami visible, entièrement à 18\" de cette unité et hors de mêlée.", "Retirez cette unité du champ de bataille et replacez-la à 1\" de l'unité cible et hors de mêlée. Puis retirez la cible du champ de bataille et replacez-la à 1\" du point cible et hors de mêlée. Cette unité et la cible peuvent utiliser des aptitudes de MOUVEMENT à la phase de mouvement suivante (exception aux Règles de Base, 24.0)."),
"To the Last": ("", "Chaque fois qu'une unité amie sous les ordres utilise l'ordre « Ralliement », vous pouvez faire 3 jets de ralliement supplémentaires d'un D6."),
"Masters of the Arcane": ("", "Ajoutez 1 aux jets de manipulation arcanique et de bannissement des SORCIERS amis sous les ordres.\nNote : dans ce tome de bataille, les sorciers utilisent des jets de manipulation arcanique pour divers effets puissants."),
"Throngs of the Faithful": ("", "Pour le restant du tour, ajoutez 1 aux jets de blessure des attaques de mêlée des unités SIGMARITE amies qui ciblent l'unité ennemie qui utilise cette aptitude de CORPS À CORPS."),
"Dawnbringer Crusade": ("Choisissez pour utiliser cette aptitude une unité d'INFANTERIE CITIES OF SIGMAR non HÉROS amie entièrement en territoire ami.", "Si cette unité est en mêlée, elle peut se déplacer de 6\". Elle peut traverser les portées de mêlée des unités ennemies mais ne peut finir en mêlée qu'avec des unités avec lesquelles elle était en mêlée au début du mouvement. Elle n'est pas obligée de finir en mêlée.\nSi elle n'est pas en mêlée, elle peut se déplacer de 6\". Elle ne peut entrer en mêlée à aucun moment de ce mouvement."),
"Have No Mercy": ("Choisissez comme cible une unité ennemie visible.", "Jusqu'au début du round de bataille suivant, ajoutez 1 aux jets de blessure des attaques de mêlée des unités AELF CITIES OF SIGMAR amies qui ciblent cette unité ennemie tant qu'elle est endommagée ou a perdu des figurines au même tour."),
"I've Seen Worse and Killed Better": ("Choisissez comme cible une unité ennemie qui a chargé à ce tour et qui est en mêlée avec des unités DUARDIN CITIES OF SIGMAR amies qui n'ont pas chargé à ce tour.", "Jetez un dé. Sur 4+, les aptitudes d'arme des attaques de mêlée de la cible, sauf Compagnon, n'ont aucun effet pour le restant du tour."),
"Stentorian General": ("", "Soustrayez 1 aux jets de protection des unités ennemies tant qu'elles sont en mêlée avec des unités amies visibles, entièrement à 12\" de cette unité et sous les ordres."),
"Beloved Leader": ("", "Ignorez les modificateurs négatifs appliqués par des aptitudes ennemies aux jets de touche et de blessure des attaques des unités amies visibles, entièrement à 12\" de cette unité et sous les ordres."),
"Grizzled Drillmaster": ("", "Les autres unités amies visibles ont une PROTECTION (6+) tant qu'elles sont entièrement à 12\" de cette unité et sous les ordres."),
"Cosmopolitan Leader": ("Choisissez comme cible une unité d'INFANTERIE ou de CAVALERIE CITIES OF SIGMAR amie entièrement à 12\" de cette unité. Si cette unité est HUMAINE, choisissez jusqu'à 3 unités éligibles à la place.", "Jetez un dé. Sur 3+, jusqu'au début de votre prochain tour :\n• Si la cible est HUMAINE, ajoutez 1 aux jets de blessure de ses attaques de mêlée.\n• Si la cible est DUARDIN, ajoutez 1 à ses jets de charge.\n• Si la cible est AELF, ajoutez 3 à son score de contrôle."),
"Draw Steel!": ("Si cette unité a chargé à ce tour, choisissez comme cible une unité HUMAINE CITIES OF SIGMAR amie qui a chargé à ce tour et est entièrement à 12\" de cette unité.", "Ajoutez 1 aux Attaques des armes de mêlée de la cible pour le restant du tour."),
"Astute Tactician": ("Choisissez comme cible une unité CITIES OF SIGMAR amie entièrement à 12\" de cette unité.", "Pour le restant du tour, ajoutez 1 aux jets de charge et 2 aux jets de course de la cible."),
"Pious Veteran": ("", "Chaque fois que vous choisissez des cibles en annonçant une aptitude de PRIÈRE d'un PRÊTRE CITIES OF SIGMAR ami, si cette unité est éligible, vous pouvez la choisir comme cible supplémentaire."),
"Bristling Attitude": ("", "Dépensez autant de dés de rage que vous le souhaitez. Si le niveau de fureur de votre adversaire est inférieur au vôtre, il doit l'augmenter de 1 (7 maximum). Puis jetez X dés, X étant le nombre de dés de rage dépensés. Pour chaque 3+, soustrayez 1 au jet de charge."),
"Holy Aegis": ("Choisissez un PRÊTRE CITIES OF SIGMAR ami pour réciter cette prière, choisissez comme cible une unité CITIES OF SIGMAR amie visible entièrement à 12\" de lui, puis faites un jet de récitation d'un D6.", "Si le jet de récitation était de 7+, vous pouvez choisir une autre unité éligible comme seconde cible. Jusqu'au début de votre prochain tour, ignorez le premier dégât qui devrait être alloué à chaque cible à chaque phase."),
"Benediction of the High Heavens": ("Choisissez un PRÊTRE CITIES OF SIGMAR ami pour réciter cette prière, choisissez comme cible une unité CITIES OF SIGMAR amie visible entièrement à 12\" de lui, puis faites un jet de récitation d'un D6.", "Soignez (D3) la cible et le récitant. Si le jet de récitation était de 7+, Soignez (D3) à la place chaque unité CITIES OF SIGMAR amie visible entièrement à 12\" du récitant."),
"Reckoning of Sinners": ("Choisissez un PRÊTRE CITIES OF SIGMAR ami pour réciter cette prière, choisissez comme cible une unité CITIES OF SIGMAR amie visible entièrement à 12\" de lui, puis faites un jet de récitation d'un D6.", "Si le jet de récitation était de 10+, vous pouvez choisir une autre unité éligible comme seconde cible. Jusqu'au début de votre prochain tour, le score de contrôle des unités ennemies est de 1 maximum tant qu'elles sont en mêlée avec l'une des cibles."),
"Curse of Scorched Metal": ("Choisissez un SORCIER CITIES OF SIGMAR ami pour lancer ce sort, choisissez comme cible une unité ennemie visible à 18\" de lui, puis faites un jet de lancement de 2D6.", "Jusqu'au début de votre prochain tour, la première fois que la cible utilise une aptitude d'ATTAQUE, pour chaque jet de touche non modifié de 1 de ses attaques dans le cadre de cette aptitude, infligez-lui 1 dégât mortel après sa résolution."),
"High Star's Light": ("Choisissez un SORCIER CITIES OF SIGMAR ami pour lancer ce sort, choisissez comme cible une unité CITIES OF SIGMAR amie visible entièrement à 12\" de lui, puis faites un jet de lancement de 2D6.", "Ajoutez 1 aux Attaques des armes de mêlée de la cible pour le restant du tour."),
"Speed of the Twin-tailed Comet": ("Choisissez un SORCIER CITIES OF SIGMAR ami pour lancer ce sort, puis faites un jet de lancement de 2D6.", "Pour le restant du tour, ajoutez 3\" au Mouvement des unités CITIES OF SIGMAR non MACHINE DE GUERRE amies tant qu'elles sont entièrement à 12\" du lanceur et visibles de lui."),
"Prototype Arco-Combustor Uninhibitor": ("", "Pour le restant du tour :\n• Ajoutez 3\" au Mouvement de cette unité.\n• Cette unité peut utiliser des aptitudes de TIR même si elle a utilisé une aptitude de REPLI au même tour.\n• Aucun dégât mortel ne lui est infligé par les aptitudes de REPLI."),
"Emergency Bellows": ("", "Retirez 1 pion de chaleur de cette unité."),
"Grapple-net Launcher": ("Si cette unité n'a pas chargé à ce tour, choisissez comme cible une unité ennemie en mêlée avec elle et qui a chargé à ce tour.", "Soustrayez 1 aux Attaques des armes de mêlée de la cible pour le restant du tour."),
"Twin-tailed Comet of Honour": ("", "Tant que cette unité a des champions, ajoutez 5 à son score de contrôle."),
"The Living City Cross": ("", "Tant que cette unité a des champions, soustrayez 1 aux jets de touche des attaques de tir qui la ciblent."),
"Aqshian Order of Merit": ("", "Tant que cette unité a des champions, si une unité ennemie en mêlée avec elle utilise l'aptitude « Éruption de Fureur », sur un jet de touche non modifié de 6, n'infligez pas les D3 dégâts mortels supplémentaires à chaque unité en mêlée avec elle."),
}
T["Battle Damaged"]=("", "Tant que cette unité a 10 points de dégâts ou plus :\n• Les Attaques de ses Crushing Iron Feet sont de 3.\n• Son score de contrôle est de 5.")

# Terrain de faction
T['Hauled to War'] = ('', 'Après la résolution de l\'aptitude « Mouvement Normal », choisissez un point du champ de bataille à 1" de l\'unité qui l\'a utilisée et à 6" de cet élément de terrain. Retirez cet élément de terrain du champ de bataille et replacez-le à 1" de ce point et à plus de 3" de toutes les unités ennemies.')
T['Fury of the Faithful'] = ('Choisissez comme cible une unité ennemie visible à 6" de cet élément de terrain.', "Si cet élément de terrain est en mêlée, appliquez l'effet ci-dessous. Sinon, jetez un dé : sur 3+, appliquez-le.\nPour le restant du tour, les armes de mêlée des unités d'INFANTERIE et de CAVALERIE CITIES OF SIGMAR amies ont Crit (Blessure auto) pour les attaques qui ciblent cette unité ennemie.")

# Compagnons (repris de fr_ror.py)
T.update({
    'Hidden Agents': ("Choisissez cette unité et une unité de Callis and Toll amie si elles n'ont pas été déployées.", "Placez ces unités en réserve dans l'ombre. Elles sont maintenant déployées."),
    'Emerge from the Shadows': ("Choisissez cette unité si elle est dans l'ombre.", 'Placez cette unité n\'importe où sur le champ de bataille à plus de 6" de la cible désignée et à plus de 9" de toutes les autres unités ennemies. Puis placez l\'unité de Callis and Toll qui est dans l\'ombre entièrement à 6" ou moins de cette unité, à plus de 6" de la cible désignée et à plus de 9" de toutes les autres unités ennemies.'),
    'Saviours of Cinderfall': ('', "Tant qu'une unité de Callis and Toll amie est entièrement dans la portée de combat de cette unité, cette unité et cette unité amie ont PROTECTION (5+)."),
})
